  // 连接断开，读不到完整错误。这里继续把请求体读完（排空，天然带背压），
  // 等请求正常结束后再回复，客户端只要发完并保持连接等待，就能收到完整可解析的 400。
  // 超限后的字节不再缓存：绝不能拿已收到的前缀去解析，更不能截断后尝试保存。
  try {
    for await (const chunk of req as AsyncIterable<Buffer>) {
      size += chunk.length;
