221	// 非法 JSON 正文，精确凑到 target 字节（整份大小判定与 JSON 解析的优先级边界用）
222	function malformedBody(target: number): Buffer {
223	  const head = Buffer.from('{not json', 'utf8');
224	  const body = Buffer.concat([head, Buffer.from(' '.repeat(Math.max(0, target - head.length)), 'ascii')]);
225	  assert.equal(body.length, target);
226	  return body;
227	}
