229	// 合法 JSON，但在最后一个字段与结束括号之间插入 target 所需的字段外空白：
230	// 字段外的空白也计入整份请求体大小
231	function whitespaceBody(target: number): Buffer {
232	  const core = JSON.stringify(FIELDS);
233	  const head = core.slice(0, -1);
234	  const needed = target - Buffer.byteLength(head, 'utf8') - 1;
235	  assert.ok(needed >= 0);
236	  const body = Buffer.from(head + ' '.repeat(needed) + '}', 'utf8');
237	  assert.equal(body.length, target);
238	  JSON.parse(body.toString('utf8')); // 自身保证合法
239	  return body;
240	}
