// 用户主动输入的“�”本身以合法 UTF-8（EF BF BD）编码，解码结果就是普通文字，照常进入后续判定。
const rawBody = Buffer.concat(chunks);
let bodyText: string;
try {
  bodyText = UTF8_DECODER.decode(rawBody);
} catch {
  respond(res, 400, { error: '请求体不是有效的 UTF-8' });
